    for apex in range(w):
        if grid[0][apex] != marker or marker == 0:
            continue
        for r in range(h):
            left, right = apex - r, apex + r
            for c in range(max(0, left + 1), min(w - 1, right - 1) + 1):
                if out[r][c] == 0:
                    out[r][c] = fill
    return out

